/* This is based on the Adaptive Huffman algorithm described in Sayood's Data

 * Compression book.  The ranks are not actually stored, but implicitly defined

 * by the location of a node within a doubly-linked list */



#include "q_shared.h"

#include "qcommon.h"



static int			bloc = 0;



void	Huff_putBit( int bit, byte *fout, int *offset) {

	bloc = *offset;

	if ((bloc&7) == 0) {

		fout[(bloc>>3)] = 0;

	}

	fout[(bloc>>3)] |= bit << (bloc&7);

	bloc++;

	*offset = bloc;

}



int		Huff_getBloc(void)

{

	return bloc;

}



void	Huff_setBloc(int _bloc)

{

	bloc = _bloc;

}



int		Huff_getBit( byte *fin, int *offset) {

	int t;

	bloc = *offset;

	t = (fin[(bloc>>3)] >> (bloc&7)) & 0x1;

	bloc++;

	*offset = bloc;

	return t;

}



/* Add a bit to the output file (buffered) */

static void add_bit (char bit, byte *fout) {

	if ((bloc&7) == 0) {

		fout[(bloc>>3)] = 0;

	}

	fout[(bloc>>3)] |= bit << (bloc&7);

	bloc++;

}



/* Receive one bit from the input file (buffered) */

static int get_bit (byte *fin) {

	int t;

	t = (fin[(bloc>>3)] >> (bloc&7)) & 0x1;

	bloc++;

	return t;

}



static node_t **get_ppnode(huff_t* huff) {

	node_t **tppnode;

	if (!huff->freelist) {

		return &(huff->nodePtrs[huff->blocPtrs++]);

	} else {

		tppnode = huff->freelist;

		huff->freelist = (node_t **)*tppnode;

		return tppnode;

	}

}



static void free_ppnode(huff_t* huff, node_t **ppnode) {

	*ppnode = (node_t *)huff->freelist;

	huff->freelist = ppnode;

}



/* Swap the location of these two nodes in the tree */

static void swap (huff_t* huff, node_t *node1, node_t *node2) { 

	node_t *par1, *par2;



	par1 = node1->parent;

	par2 = node2->parent;



	if (par1) {

		if (par1->left == node1) {

			par1->left = node2;

		} else {

	      par1->right = node2;

		}

	} else {

		huff->tree = node2;

	}



	if (par2) {

		if (par2->left == node2) {

			par2->left = node1;

		} else {

			par2->right = node1;

		}

	} else {

		huff->tree = node1;

	}



	node1->parent = par2;

	node2->parent = par1;

}



/* Swap these two nodes in the linked list (update ranks) */

static void swaplist(node_t *node1, node_t *node2) {

	node_t *par1;



	par1 = node1->next;

	node1->next = node2->next;

	node2->next = par1;



	par1 = node1->prev;

	node1->prev = node2->prev;

	node2->prev = par1;



	if (node1->next == node1) {

		node1->next = node2;

	}

	if (node2->next == node2) {

		node2->next = node1;

	}

	if (node1->next) {

		node1->next->prev = node1;

	}

	if (node2->next) {

		node2->next->prev = node2;

	}

	if (node1->prev) {

		node1->prev->next = node1;

	}

	if (node2->prev) {

		node2->prev->next = node2;

	}

}



/* Do the increments */

static void increment(huff_t* huff, node_t *node) {

	node_t *lnode;



	if (!node) {

		return;

	}



	if (node->next != NULL && node->next->weight == node->weight) {

	    lnode = *node->head;

		if (lnode != node->parent) {

			swap(huff, lnode, node);

		}

		swaplist(lnode, node);

	}

	if (node->prev && node->prev->weight == node->weight) {

		*node->head = node->prev;

	} else {

	    *node->head = NULL;

		free_ppnode(huff, node->head);

	}

	node->weight++;

	if (node->next && node->next->weight == node->weight) {

		node->head = node->next->head;

	} else { 

		node->head = get_ppnode(huff);

		*node->head = node;

	}

	if (node->parent) {

		increment(huff, node->parent);

		if (node->prev == node->parent) {

			swaplist(node, node->parent);

			if (*node->head == node) {

				*node->head = node->parent;

			}

		}

	}

}



void Huff_addRef(huff_t* huff, byte ch) {

	node_t *tnode, *tnode2;

	if (huff->loc[ch] == NULL) { /* if this is the first transmission of this node */

		tnode = &(huff->nodeList[huff->blocNode++]);

		tnode2 = &(huff->nodeList[huff->blocNode++]);



		tnode2->symbol = INTERNAL_NODE;

		tnode2->weight = 1;

		tnode2->next = huff->lhead->next;

		if (huff->lhead->next) {

			huff->lhead->next->prev = tnode2;

			if (huff->lhead->next->weight == 1) {

				tnode2->head = huff->lhead->next->head;

			} else {

				tnode2->head = get_ppnode(huff);

				*tnode2->head = tnode2;

			}

		} else {

			tnode2->head = get_ppnode(huff);

			*tnode2->head = tnode2;

		}

		huff->lhead->next = tnode2;

		tnode2->prev = huff->lhead;



		tnode->symbol = ch;

		tnode->weight = 1;

		tnode->next = huff->lhead->next;

		if (huff->lhead->next) {

			huff->lhead->next->prev = tnode;

			if (huff->lhead->next->weight == 1) {

				tnode->head = huff->lhead->next->head;

			} else {

				/* this should never happen */

				tnode->head = get_ppnode(huff);

				*tnode->head = tnode2;

		    }

		} else {

			/* this should never happen */

			tnode->head = get_ppnode(huff);

			*tnode->head = tnode;

		}

		huff->lhead->next = tnode;

		tnode->prev = huff->lhead;

		tnode->left = tnode->right = NULL;



		if (huff->lhead->parent) {

			if (huff->lhead->parent->left == huff->lhead) { /* lhead is guaranteed to by the NYT */

				huff->lhead->parent->left = tnode2;

			} else {

				huff->lhead->parent->right = tnode2;

			}

		} else {

			huff->tree = tnode2; 

		}



		tnode2->right = tnode;

		tnode2->left = huff->lhead;



		tnode2->parent = huff->lhead->parent;

		huff->lhead->parent = tnode->parent = tnode2;



		huff->loc[ch] = tnode;



		increment(huff, tnode2->parent);

	} else {

		increment(huff, huff->loc[ch]);

	}

}



/* Get a symbol */

int Huff_Receive (node_t *node, int *ch, byte *fin) {

	while (node && node->symbol == INTERNAL_NODE) {

		if (get_bit(fin)) {

			node = node->right;

		} else {

			node = node->left;

		}

	}

	if (!node) {

		return 0;

//		Com_Error(ERR_DROP, "Illegal tree!");

	}

	return (*ch = node->symbol);

}



/* Get a symbol */

void Huff_offsetReceive (node_t *node, int *ch, byte *fin, int *offset, int maxoffset) {

	bloc = *offset;

	while (node && node->symbol == INTERNAL_NODE) {

		if (bloc >= maxoffset) {

			*ch = 0;

			*offset = maxoffset + 1;

			return;

		}

		if (get_bit(fin)) {

			node = node->right;

		} else {

			node = node->left;

		}

	}

	if (!node) {

		*ch = 0;

		return;

//		Com_Error(ERR_DROP, "Illegal tree!");

	}

	*ch = node->symbol;

	*offset = bloc;

}



/* Send the prefix code for this node */

static void send(node_t *node, node_t *child, byte *fout, int maxoffset) {

	if (node->parent) {

		send(node->parent, node, fout, maxoffset);

	}

	if (child) {

		if (bloc >= maxoffset) {

			bloc = maxoffset + 1;

			return;

		}

		if (node->right == child) {

			add_bit(1, fout);

		} else {

			add_bit(0, fout);

		}

	}

}



/* Send a symbol */

void Huff_transmit (huff_t *huff, int ch, byte *fout, int maxoffset) {

	int i;

	if (huff->loc[ch] == NULL) { 

		/* node_t hasn't been transmitted, send a NYT, then the symbol */

		Huff_transmit(huff, NYT, fout, maxoffset);

		for (i = 7; i >= 0; i--) {

			add_bit((char)((ch >> i) & 0x1), fout);

		}

	} else {

		send(huff->loc[ch], NULL, fout, maxoffset);

	}

}



void Huff_offsetTransmit (huff_t *huff, int ch, byte *fout, int *offset, int maxoffset) {

	bloc = *offset;

	send(huff->loc[ch], NULL, fout, maxoffset);

	*offset = bloc;

}



void Huff_Decompress(msg_t *mbuf, int offset) {

	int			ch, cch, i, j, size;

	byte		seq[65536];

	byte*		buffer;

	huff_t		huff;



	size = mbuf->cursize - offset;

	buffer = mbuf->data + offset;



	if ( size <= 0 ) {

		return;

	}



	Com_Memset(&huff, 0, sizeof(huff_t));

	// Initialize the tree & list with the NYT node 

	huff.tree = huff.lhead = huff.ltail = huff.loc[NYT] = &(huff.nodeList[huff.blocNode++]);

	huff.tree->symbol = NYT;

	huff.tree->weight = 0;

	huff.lhead->next = huff.lhead->prev = NULL;

	huff.tree->parent = huff.tree->left = huff.tree->right = NULL;



	cch = buffer[0]*256 + buffer[1];

	// don't overflow with bad messages

	if ( cch > mbuf->maxsize - offset ) {

		cch = mbuf->maxsize - offset;

	}

	bloc = 16;



	for ( j = 0; j < cch; j++ ) {

		ch = 0;

		// don't overflow reading from the messages

		// FIXME: would it be better to have an overflow check in get_bit ?

		if ( (bloc >> 3) > size ) {

			seq[j] = 0;

			break;

		}

		Huff_Receive(huff.tree, &ch, buffer);				/* Get a character */

		if ( ch == NYT ) {								/* We got a NYT, get the symbol associated with it */

			ch = 0;

			for ( i = 0; i < 8; i++ ) {

				ch = (ch<<1) + get_bit(buffer);

			}

		}



		seq[j] = ch;									/* Write symbol */



		Huff_addRef(&huff, (byte)ch);								/* Increment node */

	}

	mbuf->cursize = cch + offset;

	Com_Memcpy(mbuf->data + offset, seq, cch);

}



extern 	int oldsize;



void Huff_Compress(msg_t *mbuf, int offset) {

	int			i, ch, size;

	byte		seq[65536];

	byte*		buffer;

	huff_t		huff;



	size = mbuf->cursize - offset;

	buffer = mbuf->data+ + offset;



	if (size<=0) {

		return;

	}



	Com_Memset(&huff, 0, sizeof(huff_t));

	// Add the NYT (not yet transmitted) node into the tree/list */

	huff.tree = huff.lhead = huff.loc[NYT] =  &(huff.nodeList[huff.blocNode++]);

	huff.tree->symbol = NYT;

	huff.tree->weight = 0;

	huff.lhead->next = huff.lhead->prev = NULL;

	huff.tree->parent = huff.tree->left = huff.tree->right = NULL;



	seq[0] = (size>>8);

	seq[1] = size&0xff;



	bloc = 16;



	for (i=0; i<size; i++ ) {

		ch = buffer[i];

		Huff_transmit(&huff, ch, seq, size<<3);						/* Transmit symbol */

		Huff_addRef(&huff, (byte)ch);								/* Do update */

	}



	bloc += 8;												// next byte



	mbuf->cursize = (bloc>>3) + offset;

	Com_Memcpy(mbuf->data+offset, seq, (bloc>>3));

}



void Huff_Init(huffman_t *huff) {



	Com_Memset(&huff->compressor, 0, sizeof(huff_t));

	Com_Memset(&huff->decompressor, 0, sizeof(huff_t));



	// Initialize the tree & list with the NYT node 

	huff->decompressor.tree = huff->decompressor.lhead = huff->decompressor.ltail = huff->decompressor.loc[NYT] = &(huff->decompressor.nodeList[huff->decompressor.blocNode++]);

	huff->decompressor.tree->symbol = NYT;

	huff->decompressor.tree->weight = 0;

	huff->decompressor.lhead->next = huff->decompressor.lhead->prev = NULL;

	huff->decompressor.tree->parent = huff->decompressor.tree->left = huff->decompressor.tree->right = NULL;



	// Add the NYT (not yet transmitted) node into the tree/list */

	huff->compressor.tree = huff->compressor.lhead = huff->compressor.loc[NYT] =  &(huff->compressor.nodeList[huff->compressor.blocNode++]);

	huff->compressor.tree->symbol = NYT;

	huff->compressor.tree->weight = 0;

	huff->compressor.lhead->next = huff->compressor.lhead->prev = NULL;

	huff->compressor.tree->parent = huff->compressor.tree->left = huff->compressor.tree->right = NULL;

}

/* drivers/net/ifb.c:



	The purpose of this driver is to provide a device that allows

	for sharing of resources:



	1) qdiscs/policies that are per device as opposed to system wide.

	ifb allows for a device which can be redirected to thus providing

	an impression of sharing.



	2) Allows for queueing incoming traffic for shaping instead of

	dropping.



	The original concept is based on what is known as the IMQ

	driver initially written by Martin Devera, later rewritten

	by Patrick McHardy and then maintained by Andre Correa.



	You need the tc action  mirror or redirect to feed this device

       	packets.



	This program is free software; you can redistribute it and/or

	modify it under the terms of the GNU General Public License

	as published by the Free Software Foundation; either version

	2 of the License, or (at your option) any later version.



  	Authors:	Jamal Hadi Salim (2005)



*/





#include <linux/module.h>

#include <linux/kernel.h>

#include <linux/netdevice.h>

#include <linux/etherdevice.h>

#include <linux/init.h>

#include <linux/interrupt.h>

#include <linux/moduleparam.h>

#include <net/pkt_sched.h>

#include <net/net_namespace.h>



#define TX_Q_LIMIT    32

struct ifb_private {

	struct tasklet_struct   ifb_tasklet;

	int     tasklet_pending;



	struct u64_stats_sync	rsync;

	struct sk_buff_head     rq;

	u64 rx_packets;

	u64 rx_bytes;



	struct u64_stats_sync	tsync;

	struct sk_buff_head     tq;

	u64 tx_packets;

	u64 tx_bytes;

};



static int numifbs = 2;



static void ri_tasklet(unsigned long dev);

static netdev_tx_t ifb_xmit(struct sk_buff *skb, struct net_device *dev);

static int ifb_open(struct net_device *dev);

static int ifb_close(struct net_device *dev);



static void ri_tasklet(unsigned long dev)

{

	struct net_device *_dev = (struct net_device *)dev;

	struct ifb_private *dp = netdev_priv(_dev);

	struct netdev_queue *txq;

	struct sk_buff *skb;



	txq = netdev_get_tx_queue(_dev, 0);

	if ((skb = skb_peek(&dp->tq)) == NULL) {

		if (__netif_tx_trylock(txq)) {

			skb_queue_splice_tail_init(&dp->rq, &dp->tq);

			__netif_tx_unlock(txq);

		} else {

			/* reschedule */

			goto resched;

		}

	}



	while ((skb = __skb_dequeue(&dp->tq)) != NULL) {

		u32 from = G_TC_FROM(skb->tc_verd);



		skb->tc_verd = 0;

		skb->tc_verd = SET_TC_NCLS(skb->tc_verd);



		u64_stats_update_begin(&dp->tsync);

		dp->tx_packets++;

		dp->tx_bytes += skb->len;

		u64_stats_update_end(&dp->tsync);



		rcu_read_lock();

		skb->dev = dev_get_by_index_rcu(&init_net, skb->skb_iif);

		if (!skb->dev) {

			rcu_read_unlock();

			dev_kfree_skb(skb);

			_dev->stats.tx_dropped++;

			if (skb_queue_len(&dp->tq) != 0)

				goto resched;

			break;

		}

		rcu_read_unlock();

		skb->skb_iif = _dev->ifindex;



		if (from & AT_EGRESS) {

			dev_queue_xmit(skb);

		} else if (from & AT_INGRESS) {

			skb_pull(skb, skb->dev->hard_header_len);

			netif_receive_skb(skb);

		} else

			BUG();

	}



	if (__netif_tx_trylock(txq)) {

		if ((skb = skb_peek(&dp->rq)) == NULL) {

			dp->tasklet_pending = 0;

			if (netif_queue_stopped(_dev))

				netif_wake_queue(_dev);

		} else {

			__netif_tx_unlock(txq);

			goto resched;

		}

		__netif_tx_unlock(txq);

	} else {

resched:

		dp->tasklet_pending = 1;

		tasklet_schedule(&dp->ifb_tasklet);

	}



}



static struct rtnl_link_stats64 *ifb_stats64(struct net_device *dev,

					     struct rtnl_link_stats64 *stats)

{

	struct ifb_private *dp = netdev_priv(dev);

	unsigned int start;



	do {

		start = u64_stats_fetch_begin_bh(&dp->rsync);

		stats->rx_packets = dp->rx_packets;

		stats->rx_bytes = dp->rx_bytes;

	} while (u64_stats_fetch_retry_bh(&dp->rsync, start));



	do {

		start = u64_stats_fetch_begin_bh(&dp->tsync);



		stats->tx_packets = dp->tx_packets;

		stats->tx_bytes = dp->tx_bytes;



	} while (u64_stats_fetch_retry_bh(&dp->tsync, start));



	stats->rx_dropped = dev->stats.rx_dropped;

	stats->tx_dropped = dev->stats.tx_dropped;



	return stats;

}





static const struct net_device_ops ifb_netdev_ops = {

	.ndo_open	= ifb_open,

	.ndo_stop	= ifb_close,

	.ndo_get_stats64 = ifb_stats64,

	.ndo_start_xmit	= ifb_xmit,

	.ndo_validate_addr = eth_validate_addr,

};



#define IFB_FEATURES (NETIF_F_NO_CSUM | NETIF_F_SG  | NETIF_F_FRAGLIST	| \

		      NETIF_F_TSO_ECN | NETIF_F_TSO | NETIF_F_TSO6	| \

		      NETIF_F_HIGHDMA | NETIF_F_HW_VLAN_TX)



static void ifb_setup(struct net_device *dev)

{

	/* Initialize the device structure. */

	dev->destructor = free_netdev;

	dev->netdev_ops = &ifb_netdev_ops;



	/* Fill in device structure with ethernet-generic values. */

	ether_setup(dev);

	dev->tx_queue_len = TX_Q_LIMIT;



	dev->features |= IFB_FEATURES;

	dev->vlan_features |= IFB_FEATURES;



	dev->flags |= IFF_NOARP;

	dev->flags &= ~IFF_MULTICAST;

	dev->priv_flags &= ~IFF_XMIT_DST_RELEASE;

	random_ether_addr(dev->dev_addr);

}



static netdev_tx_t ifb_xmit(struct sk_buff *skb, struct net_device *dev)

{

	struct ifb_private *dp = netdev_priv(dev);

	u32 from = G_TC_FROM(skb->tc_verd);



	u64_stats_update_begin(&dp->rsync);

	dp->rx_packets++;

	dp->rx_bytes += skb->len;

	u64_stats_update_end(&dp->rsync);



	if (!(from & (AT_INGRESS|AT_EGRESS)) || !skb->skb_iif) {

		dev_kfree_skb(skb);

		dev->stats.rx_dropped++;

		return NETDEV_TX_OK;

	}



	if (skb_queue_len(&dp->rq) >= dev->tx_queue_len) {

		netif_stop_queue(dev);

	}



	__skb_queue_tail(&dp->rq, skb);

	if (!dp->tasklet_pending) {

		dp->tasklet_pending = 1;

		tasklet_schedule(&dp->ifb_tasklet);

	}



	return NETDEV_TX_OK;

}



static int ifb_close(struct net_device *dev)

{

	struct ifb_private *dp = netdev_priv(dev);



	tasklet_kill(&dp->ifb_tasklet);

	netif_stop_queue(dev);

	__skb_queue_purge(&dp->rq);

	__skb_queue_purge(&dp->tq);

	return 0;

}



static int ifb_open(struct net_device *dev)

{

	struct ifb_private *dp = netdev_priv(dev);



	tasklet_init(&dp->ifb_tasklet, ri_tasklet, (unsigned long)dev);

	__skb_queue_head_init(&dp->rq);

	__skb_queue_head_init(&dp->tq);

	netif_start_queue(dev);



	return 0;

}



static int ifb_validate(struct nlattr *tb[], struct nlattr *data[])

{

	if (tb[IFLA_ADDRESS]) {

		if (nla_len(tb[IFLA_ADDRESS]) != ETH_ALEN)

			return -EINVAL;

		if (!is_valid_ether_addr(nla_data(tb[IFLA_ADDRESS])))

			return -EADDRNOTAVAIL;

	}

	return 0;

}



static struct rtnl_link_ops ifb_link_ops __read_mostly = {

	.kind		= "ifb",

	.priv_size	= sizeof(struct ifb_private),

	.setup		= ifb_setup,

	.validate	= ifb_validate,

};



/* Number of ifb devices to be set up by this module. */

module_param(numifbs, int, 0);

MODULE_PARM_DESC(numifbs, "Number of ifb devices");



static int __init ifb_init_one(int index)

{

	struct net_device *dev_ifb;

	int err;



	dev_ifb = alloc_netdev(sizeof(struct ifb_private),

				 "ifb%d", ifb_setup);



	if (!dev_ifb)

		return -ENOMEM;



	dev_ifb->rtnl_link_ops = &ifb_link_ops;

	err = register_netdevice(dev_ifb);

	if (err < 0)

		goto err;



	return 0;



err:

	free_netdev(dev_ifb);

	return err;

}



static int __init ifb_init_module(void)

{

	int i, err;



	rtnl_lock();

	err = __rtnl_link_register(&ifb_link_ops);



	for (i = 0; i < numifbs && !err; i++)

		err = ifb_init_one(i);

	if (err)

		__rtnl_link_unregister(&ifb_link_ops);

	rtnl_unlock();



	return err;

}



static void __exit ifb_cleanup_module(void)

{

	rtnl_link_unregister(&ifb_link_ops);

}



module_init(ifb_init_module);

module_exit(ifb_cleanup_module);

